import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Home.css';

const Home = () => {
  const [username, setUsername] = useState('');
  const [roomCode, setRoomCode] = useState('');
  const [isCreating, setIsCreating] = useState(false);
  const [isJoining, setIsJoining] = useState(false);
  const navigate = useNavigate();

  // Generate a random room ID
  const generateRoomId = () => {
    const prefixes = ['PARTY', 'WATCH', 'VIDEO', 'MOVIE', 'FUN', 'CHILL', 'BOOM', 'WOW'];
    const prefix = prefixes[Math.floor(Math.random() * prefixes.length)];
    const randomNum = Math.floor(Math.random() * 10000);
    const randomChars = Math.random().toString(36).substr(2, 4).toUpperCase();
    return `${prefix}-${randomNum}-${randomChars}`;
  };

  // Generate a random user ID
  const generateUserId = () => {
    return 'user_' + Date.now() + '_' + Math.random().toString(36).substr(2, 8);
  };

  const createRoom = () => {
    if (!username.trim()) {
      alert('✨ Please enter your name to continue!');
      return;
    }

    setIsCreating(true);
    
    // Simulate loading
    setTimeout(() => {
      const newRoomId = generateRoomId();
      const userId = generateUserId();
      const userRole = 'HOST';
      
      // Store in localStorage
      localStorage.setItem('userId', userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', userRole);
      localStorage.setItem('useMockMode', 'true');
      
      console.log('Room Created:', {
        roomId: newRoomId,
        userId: userId,
        username: username,
        role: userRole
      });
      
      alert(`🎉 Party Room Created Successfully!\n\n📋 Room Code: ${newRoomId}\n\n👑 You are the HOST!\n\n💡 Share this code with friends to join!\nThey can open this app in another tab and use "Join Party" with this code.`);
      
      navigate(`/room/${newRoomId}`);
      setIsCreating(false);
    }, 500);
  };

  const joinRoom = () => {
    if (!username.trim()) {
      alert('✨ Please enter your name first!');
      return;
    }
    if (!roomCode.trim()) {
      alert('🔑 Please enter a room code to join!');
      return;
    }

    setIsJoining(true);
    
    // Simulate loading
    setTimeout(() => {
      const userId = generateUserId();
      const userRole = 'PARTICIPANT';
      
      // Store in localStorage
      localStorage.setItem('userId', userId);
      localStorage.setItem('username', username);
      localStorage.setItem('role', userRole);
      localStorage.setItem('useMockMode', 'true');
      
      console.log('Joining Room:', {
        roomId: roomCode.toUpperCase(),
        userId: userId,
        username: username,
        role: userRole
      });
      
      alert(`🎉 Joined Room Successfully!\n\n📋 Room: ${roomCode.toUpperCase()}\n\n👤 You joined as PARTICIPANT!\n\n💡 Wait for the host to start the party!`);
      
      navigate(`/room/${roomCode.toUpperCase()}`);
      setIsJoining(false);
    }, 500);
  };

  return (
    <div className="home-container">
      <div className="home-card fade-in-up">
        <div style={{ 
          background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', 
          padding: '4px 12px', 
          borderRadius: '20px', 
          display: 'inline-block',
          marginBottom: '15px',
          fontSize: '12px',
          fontWeight: 'bold',
          color: 'white'
        }}>
          🎮 TEST MODE ACTIVE
        </div>
        
        <h1>🎬 YouTube Watch Party</h1>
        <p>Watch YouTube videos together with friends in real-time!<br />Sync, chat, and enjoy together! 🚀</p>
        
        <div className="input-group">
          <input
            type="text"
            placeholder="✨ Enter your awesome name"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && createRoom()}
          />
        </div>

        <div className="action-buttons">
          <button 
            className="btn btn-primary"
            onClick={createRoom}
            disabled={isCreating}
            style={{
              background: isCreating ? '#ccc' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              cursor: isCreating ? 'not-allowed' : 'pointer'
            }}
          >
            {isCreating ? (
              <>
                <span className="loading-spinner"></span> Creating Room...
              </>
            ) : (
              '✨ Create New Party'
            )}
          </button>
          
          <div className="divider">OR</div>
          
          <div className="join-section">
            <input
              type="text"
              placeholder="🔑 Enter room code"
              value={roomCode}
              onChange={(e) => setRoomCode(e.target.value.toUpperCase())}
              onKeyPress={(e) => e.key === 'Enter' && joinRoom()}
            />
            <button 
              className="btn btn-primary"
              onClick={joinRoom}
              disabled={isJoining}
              style={{
                background: isJoining ? '#ccc' : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                cursor: isJoining ? 'not-allowed' : 'pointer'
              }}
            >
              {isJoining ? (
                <>
                  <span className="loading-spinner"></span> Joining...
                </>
              ) : (
                '🚪 Join Party'
              )}
            </button>
          </div>
        </div>

        <div className="features">
          <div className="feature-badge">✨ Real-time Sync</div>
          <div className="feature-badge">👑 Role-based Access</div>
          <div className="feature-badge">💬 Live Chat</div>
          <div className="feature-badge">🎬 YouTube Integration</div>
        </div>

        <div style={{ 
          marginTop: '25px', 
          padding: '15px', 
          background: '#f8f9fa', 
          borderRadius: '12px', 
          fontSize: '13px',
          borderLeft: '4px solid #667eea'
        }}>
          <strong>📖 How to Test Two-Way Sync:</strong><br/>
          <br/>
          <strong>1️⃣ Tab 1 (Host):</strong><br/>
          • Enter your name<br/>
          • Click "Create New Party"<br/>
          • Copy the Room Code shown<br/>
          <br/>
          <strong>2️⃣ Tab 2 (Participant):</strong><br/>
          • Open this app in another browser tab<br/>
          • Enter a different name<br/>
          • Paste the Room Code<br/>
          • Click "Join Party"<br/>
          <br/>
          <strong>3️⃣ Watch Real-Time Sync:</strong><br/>
          • Play/Pause in Tab 1 → Tab 2 follows<br/>
          • Seek video in Tab 1 → Both jump to same time<br/>
          • Change video in Tab 1 → Both load new video<br/>
          • Host can make participant Moderator<br/>
          • Chat messages appear in both tabs! 🎉
        </div>

        <div style={{ marginTop: '15px', fontSize: '11px', color: '#999', textAlign: 'center' }}>
          💡 Tip: Open two browser windows side by side to see real-time sync in action!
        </div>
      </div>
    </div>
  );
};

export default Home;
